// === NODE 1: NORMALIZAR E DETECTAR CONTEXTO ===

// Pegar dados do webhook
const messageBody = $json.body.data.body || '';
const chatId = $json.body.data.chatId;
const from = $json.body.data.from;
const messageId = $json.body.data.id;

// Normalizar texto (remover acentos para busca)
const normalize = (text) => {
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
};

const normalized = normalize(messageBody);

// === DETECTAR TIPO DE SOLICITAÇÃO ===
let tipo = 'geral';
let urgencia = false;
let categoria = null;

// Previdenciário
if (normalized.match(/auxilio|auxílio|beneficio|benefício|inss|doenca|doença|afastado|incapacitado|pericia|perícia/)) {
  tipo = 'previdenciario';

  if (normalized.match(/auxilio|beneficio/)) categoria = 'auxilio-doenca';
  if (normalized.match(/aposentadoria|invalidez/)) categoria = 'aposentadoria';
  if (normalized.match(/pericia|perícia|laudo/)) categoria = 'pericia';
}

// Família
if (normalized.match(/divorcio|divórcio|separacao|separação|separar|casal|marido|esposa/)) {
  tipo = 'familia';

  if (normalized.match(/divorcio|separacao/)) categoria = 'divorcio';
  if (normalized.match(/bens|casa|carro|dividir|partilha/)) categoria = 'divisao-bens';
  if (normalized.match(/pensao|pensão|alimentos/)) categoria = 'pensao';
}

// Acompanhamento
if (normalized.match(/processo|andamento|resultado|como esta|liberado|disponivel/)) {
  tipo = 'acompanhamento';
  categoria = 'status-processo';
}

// === DETECTAR URGÊNCIA ===
if (normalized.match(/urgente|remedio|remédio|cirurgia|preciso|dinheiro|conta|pagar/)) {
  urgencia = true;
}

// === DETECTAR NECESSIDADE DE DADOS ===
let precisaCPF = false;
if (tipo === 'acompanhamento' && !normalized.match(/\d{11}|\d{3}\.\d{3}\.\d{3}-\d{2}/)) {
  precisaCPF = true;
}

// Retornar dados estruturados
return {
  json: {
    // Dados originais
    messageOriginal: messageBody,
    chatId: chatId,
    from: from,
    messageId: messageId,

    // Dados processados
    messageNormalized: normalized,
    tipo: tipo,
    categoria: categoria,
    urgencia: urgencia,
    precisaCPF: precisaCPF,

    // Timestamp
    timestamp: new Date().toISOString()
  }
};

// === NODE 2: MONTAR PROMPT INTELIGENTE ===

const data = $input.first().json;

// System Prompt BASE
const systemPrompt = `Você é assistente virtual do escritório de advocacia Dr. Dênis Bernardo, especializado em direito previdenciário e de família.

🎯 MISSÃO:
Fazer triagem inicial de clientes, identificar necessidades e coletar dados básicos.

📜 REGRAS DE COMUNICAÇÃO:

1. TOM: Informal mas respeitoso, como conversar com vizinho de confiança
2. LINGUAGEM: Português simples, sem juridiquês. Máximo 2-3 frases
3. ERROS DO CLIENTE: Cliente escreveu errado? Entenda contexto e responda normal
   - "qanto csta" = "quanto custa"
   - "mim desculpa" = "me desculpa" 
   - "agente" = "a gente"
4. NUNCA corrija o português do cliente

💬 EXEMPLOS:
❌ ERRADO: "Desejo esclarecer que a legislação..."
✅ CERTO: "Pelo que você contou, o INSS tem que aprovar sim."

❌ ERRADO: "Não possuo informações..."
✅ CERTO: "Deixa eu ver aqui! Qual seu CPF?"

🚫 NUNCA:
- Inventar status de processo
- Dar data de perícia sem confirmação
- Prometer resultado
- Dar valor de honorários

Se não souber: "Vou anotar e o Dr. Denis te responde hoje."

SEMPRE termine: "Precisa de mais alguma coisa?" ou "Tô aqui se precisar!"`;

// === CONTEXTO ADICIONAL BASEADO NA DETECÇÃO ===
let contextoAdicional = '';

// Se for urgência
if (data.urgencia) {
  contextoAdicional += '\n\n⚠️ URGÊNCIA DETECTADA! Cliente mencionou necessidade urgente (remédio/cirurgia). Priorize empatia e rapidez.\nResponda: "Entendo que é urgente. Vou priorizar seu atendimento."';
}

// Se for acompanhamento e precisa CPF
if (data.tipo === 'acompanhamento' && data.precisaCPF) {
  contextoAdicional += '\n\n📋 Cliente quer saber status mas não informou CPF. Peça o CPF de forma natural:\n"Pra eu consultar certinho, qual seu CPF?"';
}

// Contexto por categoria
if (data.categoria === 'auxilio-doenca') {
  contextoAdicional += '\n\n💡 CONTEXTO: Auxílio-doença é para incapacidade temporária. Precisa 12 meses de contribuição INSS. Ofereça agendar consulta.';
}

if (data.categoria === 'divorcio') {
  contextoAdicional += '\n\n💡 CONTEXTO: Em divórcio consensual, bens são divididos meio a meio (regra geral). Pergunte se têm filhos e se já conversaram sobre divisão.';
}

if (data.categoria === 'divisao-bens') {
  contextoAdicional += '\n\n💡 CONTEXTO: Sair de casa NÃO é abandono. Não perde direitos aos bens. Mas recomende formalizar separação logo.';
}

// === MONTAR USER PROMPT ===
const userPrompt = `${contextoAdicional}

TIPO DA SOLICITAÇÃO: ${data.tipo}
CATEGORIA: ${data.categoria || 'não identificada'}

MENSAGEM DO CLIENTE:
"${data.messageOriginal}"

Responda de forma clara, curta (2-3 frases) e empática.`;

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,
    // Passar dados originais pra frente
    chatId: data.chatId,
    from: data.from,
    messageId: data.messageId,
    tipo: data.tipo,
    urgencia: data.urgencia
  }
};

// === NODE 3: LIMPAR E ANALISAR RESPOSTA ===

// Pegar resposta do LLM
let text = $input.first().json.text;

// Remover tags <think>...</think>
text = text.replace(/<think>[\s\S]*?<\/think>/g, '');

// Limpar espaços extras (mantém quebras de linha)
text = text.trim();

// === DETECTAR SE RESPOSTA PEDIU AÇÃO ===
let acaoDetectada = null;

if (text.match(/qual seu cpf|me passa o cpf|preciso do cpf/i)) {
  acaoDetectada = 'coletar_cpf';
}

if (text.match(/quer agendar|posso agendar|marcar consulta/i)) {
  acaoDetectada = 'agendar_consulta';
}

if (text.match(/vou anotar|dr\.? denis te responde|falar com advogado/i)) {
  acaoDetectada = 'escalar_humano';
}

// Pegar dados do node anterior
const prevData = $item("0").$node["2. Montar Prompt Inteligente"].json;

return {
  json: {
    chatId: prevData.chatId,
    text: text,
    acaoDetectada: acaoDetectada,
    tipo: prevData.tipo,
    urgencia: prevData.urgencia,
    messageId: prevData.messageId
  }
};
